python3 << 'PYEOF'
import json

with open('/home/ubuntu/.claude-account-5/projects/-home-ubuntu--agent-ml-research-idea-gen-0509-8-projects-acr-vla-conformal-refinement--claude-sessions-agent-bbd03d76/8f53d880-cb6b-406b-b330-83f9c7aac72e/tool-results/mcp-agent-ml-research-read_registry-1779934880498.txt') as f:
    data = json.load(f)
registry = json.loads(data['result'])
exps = registry['data']['experiments']

# 1. Find ALL Pi05 Adaptive experiments (not always-on, not vla-only, not baseline)
# Adaptive = uses conformal gating with tau > 0.001
print("=" * 80)
print("Pi05 ADAPTIVE experiments (DONE, conclusion=success, with SR)")
print("=" * 80)

adaptive = []
for eid, e in exps.items():
    if 'pi05' not in eid.lower():
        continue
    if 'vla-only' in eid or 'vla_only' in eid or 'baseline' in eid:
        continue
    if 'always-on' in eid or 'always_on' in eid:
        continue
    if e.get('conclusion') not in ['success', 'negative']:
        continue
    metrics = e.get('metrics', {})
    sr = metrics.get('success_rate')
    if sr is None or sr == 0 or sr == 'N/A':
        continue

    # Determine suite from exp_id or hypothesis
    suite = 'unknown'
    eid_lower = eid.lower()
    for s in ['object', 'spatial', 'goal', 'long']:
        if s in eid_lower:
            suite = s
            break
    if suite == 'unknown':
        hyp = e.get('hypothesis', '').lower()
        for s in ['object', 'spatial', 'goal', 'long']:
            if s in hyp:
                suite = s
                break

    # Get tau from spec command or exp_id
    spec = e.get('spec', {})
    cmd = spec.get('command', '')
    tau = 'unknown'
    if 'conformal_threshold' in cmd:
        import re
        m = re.search(r'conformal_threshold\s+([0-9.]+)', cmd)
        if m:
            tau = m.group(1)
    elif 'tau' in eid:
        m = re.search(r'tau(\d+)', eid)
        if m:
            tau = f"0.{m.group(1)}" if len(m.group(1)) <= 2 else m.group(1)

    server = spec.get('server', 'unknown')
    seed = spec.get('seed', 'unknown')

    adaptive.append({
        'eid': eid, 'suite': suite, 'sr': sr, 'tau': tau, 
        'server': server, 'seed': seed, 'conclusion': e.get('conclusion')
    })

# Sort by suite then exp_id
for suite in ['object', 'spatial', 'goal', 'long']:
    entries = [a for a in adaptive if a['suite'] == suite]
    if entries:
        print(f"\n--- {suite.upper()} ---")
        for a in sorted(entries, key=lambda x: x['eid']):
            print(f"  {a['eid']:55s} | SR={str(a['sr']):8s} | tau={a['tau']:8s} | seed={str(a['seed']):5s} | server={a['server']:15s} | {a['conclusion']}")

unknown = [a for a in adaptive if a['suite'] == 'unknown']
if unknown:
    print(f"\n--- UNKNOWN SUITE ---")
    for a in unknown:
        print(f"  {a['eid']:55s} | SR={str(a['sr']):8s} | tau={a['tau']:8s} | server={a['server']}")

# 2. Pi05 VLA-only with valid SR
print("\n" + "=" * 80)
print("Pi05 VLA-ONLY experiments (DONE, conclusion=success, with SR)")
print("=" * 80)

for suite in ['object', 'spatial', 'goal', 'long']:
    entries = []
    for eid, e in exps.items():
        if 'pi05' not in eid.lower():
            continue
        if 'vla-only' not in eid and 'vla_only' not in eid:
            continue
        if e.get('conclusion') != 'success':
            continue
        metrics = e.get('metrics', {})
        sr = metrics.get('success_rate')
        if sr is None or sr == 0 or sr == 'N/A':
            continue
        if suite not in eid.lower():
            continue
        spec = e.get('spec', {})
        server = spec.get('server', 'unknown')
        seed = spec.get('seed', 'unknown')
        entries.append({'eid': eid, 'sr': sr, 'server': server, 'seed': seed})

    if entries:
        print(f"\n--- {suite.upper()} ---")
        for a in sorted(entries, key=lambda x: x['eid']):
            print(f"  {a['eid']:55s} | SR={str(a['sr']):8s} | seed={str(a['seed']):5s} | server={a['server']}")

PYEOF
